<script setup>
import {computed,ref} from 'vue'
import e from '../data/report-evidence.json'
const dataset=ref('FiveK');const metric=ref('psnr')
const rows=computed(()=>dataset.value==='FiveK'?[...e.fivekBaselines,{method:'Ours Top-1',psnr:23.562,ssim:.8852,refs:8,selection:'1 candidate'},{method:'Ours Best-of-3',psnr:25.191,ssim:.8983,refs:8,selection:'3 outputs; oracle'},{method:'Ours Best-of-5',psnr:26.214,ssim:.9048,refs:8,selection:'5 outputs; oracle'}]:e.ppsd)
const value=v=>v.toFixed(metric.value==='psnr'?3:4)
</script>
<template><div class="stack"><div class="row spread"><div class="tabs"><button v-for="d in ['FiveK','PPSD']" :key="d" :aria-pressed="dataset===d" @click.stop="dataset=d">{{d}}</button></div><div class="tabs"><button :aria-pressed="metric==='psnr'" @click.stop="metric='psnr'">PSNR</button><button :aria-pressed="metric==='ssim'" @click.stop="metric='ssim'">SSIM</button></div></div><div class="split wide-left grow"><table class="evidence-table compact"><thead><tr><th>Method</th><th class="numeric">{{metric==='psnr'?'PSNR (dB)':'SSIM'}}</th><th>References / selection</th></tr></thead><tbody><tr v-for="r in rows" :key="r.method" :class="{highlight:r.method.startsWith('Ours')}"><td>{{r.method}}</td><td class="numeric">{{value(r[metric])}}</td><td>{{dataset==='FiveK'?`${r.refs} refs · ${r.selection}`:r.method==='Ours'?'250 train users / 8 refs':'PrefLUT reproduction · 471 / 16'}}</td></tr></tbody></table><div class="col"><h2>Read comparisons carefully</h2><template v-if="dataset==='FiveK'"><p>RefRetouch: K references → one output.</p><p>Our Best-of-K: K outputs → oracle selection.</p><p class="note">RefRetouch has higher SSIM. Protocols differ.</p></template><template v-else><p>Baselines: report’s PrefLUT Table 1(A).</p><p>Training-user and reference counts differ.</p><p class="note">SSIM: PrefLUT 0.843 / ours 0.841†.</p></template><p class="small muted">Reported values; baselines not rerun.</p></div></div></div></template>
